/// region <Controller>

TEST_F(LoaderDSK_Test, Wd1793_ReadSector_512)
{
    DiskImage* image = load(PLUS3_FIXTURE);
    ASSERT_NE(image, nullptr);

    // Put a recognisable pattern into track 12 sector 5 (the blank disk holds 0xE5 everywhere)
    DiskImage::Track* track = image->getTrackForCylinderAndSide(12, 0);
    std::vector<uint8_t> pattern(512);
    for (size_t i = 0; i < 512; i++) pattern[i] = static_cast<uint8_t>((i * 7) ^ 0x5A);
    track->writeSectorData(4, pattern.data(), pattern.size());

    WD1793CUT fdc(_context);
    fdc.getDrive()->insertDisk(image);
    fdc._beta128Register = WD1793CUT::BETA128_COMMAND_BITS::BETA_CMD_RESET;  // MFM (the DENSITY bit selects FM)
    fdc._drive = 0;
    fdc.wakeUp();
    fdc._time = 1000;
    fdc.prolongFDDMotorRotation();
    fdc._trackRegister = 12;
    fdc._selectedDrive->setTrack(12);
    fdc._sideUp = false;
    fdc._sectorRegister = 5;
    fdc._commandRegister = 0x80;
    fdc._lastDecodedCmd = WD1793::WD_CMD_READ_SECTOR;
    fdc.cmdReadSector(0x00);

    std::vector<uint8_t> read;
    for (size_t clk = 1000; clk < 1000 + 3'500'000 * 3 && fdc._state != WD1793::S_IDLE; clk += 100)
    {
        fdc._time = clk;
        fdc.process();
        if (fdc._beta128status & WD1793::DRQ) read.push_back(fdc.readDataRegister());
    }

    EXPECT_EQ(fdc._state, WD1793::S_IDLE);
    ASSERT_EQ(read.size(), 512u);
    EXPECT_EQ(read, pattern);
    EXPECT_FALSE(fdc._statusRegister & WD1793::WDS_CRCERR);
    EXPECT_FALSE(fdc._statusRegister & WD1793::WDS_NOTFOUND);

    // An untouched sector of the blank disk reads as 512 x 0xE5
    fdc._sectorRegister = 9;
    fdc._commandRegister = 0x80;
    fdc._lastDecodedCmd = WD1793::WD_CMD_READ_SECTOR;
    fdc.cmdReadSector(0x00);
    read.clear();
    const size_t start = fdc._time + 1000;
    for (size_t clk = start; clk < start + 3'500'000 * 3 && fdc._state != WD1793::S_IDLE; clk += 100)
    {
        fdc._time = clk;
        fdc.process();
        if (fdc._beta128status & WD1793::DRQ) read.push_back(fdc.readDataRegister());
    }
    ASSERT_EQ(read.size(), 512u);
    EXPECT_EQ(read, std::vector<uint8_t>(512, 0xE5));

    fdc.getDrive()->ejectDisk();
    delete image;
}

