/// region <Negative>

TEST_F(LoaderDSK_Test, Negative_Truncated)
{
    std::vector<uint8_t> edsk = readFile(fixture(EDSK_FIXTURE));
    std::vector<uint8_t> dsk = readFile(fixture(PLUS3_FIXTURE));
    ASSERT_GT(edsk.size(), 256u + 3 * 4864);
    ASSERT_GT(dsk.size(), 256u + 5 * 4864);

    LoaderDSK loader(_context, "");
    std::vector<std::string> warnings;

    // Shorter than the disk information block
    EXPECT_EQ(loader.parse(edsk.data(), 100, warnings), nullptr);
    ASSERT_FALSE(warnings.empty());
    EXPECT_NE(warnings.back().find("truncated"), std::string::npos);

    // Cut inside the sector data of track 3 (extended)
    warnings.clear();
    EXPECT_EQ(loader.parse(edsk.data(), 256 + 3 * 4864 + 256 + 1000, warnings), nullptr);
    ASSERT_FALSE(warnings.empty());
    EXPECT_NE(warnings.back().find("truncated"), std::string::npos);

    // Cut inside the track information block of track 4 (extended)
    warnings.clear();
    EXPECT_EQ(loader.parse(edsk.data(), 256 + 3 * 4864 + 4352 + 100, warnings), nullptr);
    ASSERT_FALSE(warnings.empty());
    EXPECT_NE(warnings.back().find("truncated"), std::string::npos);

    // Cut inside track 5 of the standard image
    warnings.clear();
    EXPECT_EQ(loader.parse(dsk.data(), 256 + 5 * 4864 + 256 + 3 * 512 + 17, warnings), nullptr);
    ASSERT_FALSE(warnings.empty());
    EXPECT_NE(warnings.back().find("truncated"), std::string::npos);

    // Wrong signature
    std::vector<uint8_t> bad = dsk;
    std::memcpy(bad.data(), "NOT A DSK", 9);
    warnings.clear();
    EXPECT_EQ(loader.parse(bad.data(), bad.size(), warnings), nullptr);
    ASSERT_FALSE(warnings.empty());
    EXPECT_NE(warnings.back().find("Not a DSK"), std::string::npos);

    // Missing Track-Info signature
    bad = dsk;
    bad[256] = 'X';
    warnings.clear();
    EXPECT_EQ(loader.parse(bad.data(), bad.size(), warnings), nullptr);
    ASSERT_FALSE(warnings.empty());
    EXPECT_NE(warnings.back().find("Track-Info"), std::string::npos);

    // Impossible geometry
    bad = dsk;
    bad[0x31] = 3;
    warnings.clear();
    EXPECT_EQ(loader.parse(bad.data(), bad.size(), warnings), nullptr);
    bad[0x31] = 1;
    bad[0x30] = 0;
    warnings.clear();
    EXPECT_EQ(loader.parse(bad.data(), bad.size(), warnings), nullptr);
    bad[0x30] = 100;
    warnings.clear();
    EXPECT_EQ(loader.parse(bad.data(), bad.size(), warnings), nullptr);

    // Missing file
    LoaderDSK missing(_context, scratch("does-not-exist.dsk"));
    EXPECT_FALSE(missing.loadImage());
    EXPECT_FALSE(missing.lastWarnings().empty());

    // Nothing to save
    LoaderDSK empty(_context, "");
    EXPECT_FALSE(empty.writeImage(scratch("nothing.dsk")));
    EXPECT_FALSE(empty.lastWarnings().empty());
}

TEST_F(LoaderDSK_Test, Load_LayoutLargerThanTrack_Grows)
{
    // 18 x 256 with GAP#3 0x2A needs more than 6250 bytes: the track grows with a warning
    std::vector<uint8_t> file(256 + 256 + 18 * 256, 0);
    std::memcpy(file.data(), "EXTENDED CPC DSK File\r\nDisk-Info\r\n", 34);
    file[0x30] = 1;
    file[0x31] = 1;
    file[0x34] = static_cast<uint8_t>((256 + 18 * 256) / 256);
    uint8_t* info = file.data() + 256;
    std::memcpy(info, "Track-Info\r\n", 12);
    info[0x13] = 2;
    info[0x14] = 1;
    info[0x15] = 18;
    info[0x16] = 0x2A;
    info[0x17] = 0xE5;
    for (size_t i = 0; i < 18; i++)
    {
        uint8_t* entry = info + 0x18 + 8 * i;
        entry[2] = static_cast<uint8_t>(i + 1);
        entry[3] = 1;
        entry[6] = 0x00;
        entry[7] = 0x01;
        std::memset(file.data() + 512 + i * 256, static_cast<int>(i), 256);
    }

    LoaderDSK loader(_context, "");
    std::vector<std::string> warnings;
    DiskImage* image = loader.parse(file.data(), file.size(), warnings);
    ASSERT_NE(image, nullptr) << (warnings.empty() ? "" : warnings[0]);
    ASSERT_FALSE(warnings.empty());
    EXPECT_NE(warnings[0].find("grown"), std::string::npos);

    DiskImage::Track* track = image->getTrack(0);
    EXPECT_GT(track->rawSize(), 6250u);
    EXPECT_LE(track->rawSize(), DiskImage::RawTrack::MAX_TRACK_SIZE);
    ASSERT_EQ(track->sectorCount(), 18u);
    EXPECT_EQ(track->findSector(18)->data[0], 17);
    EXPECT_TRUE(track->findSector(18)->dataCrcValid);

    delete image;
}

